package mcpserver

import (
	"github.com/corezoid/simulator-ai/internal/publicapi"
	"github.com/mark3labs/mcp-go/server"
)

// addConsoleActors registers the composite actor tools of the Console: a chat with people and the
// cards an actor shows.
func addConsoleActors(s *server.MCPServer, c *publicapi.Client) {
	consoleTool(s, "chat_open", "Open the chat to message people (\"write to N\", \"open a chat with\"): a chat is an Events actor with data.chatType p2p or group, its participants are its access rules and its messages are comment reactions. type p2p with one other userId (from users_search) reuses the 1:1 chat of exactly you and that person, as the web UI does (ref p2pConversation_<min>_<max>), else creates it named \"<nick>:p2p:<nick>\"; type group with a title and the other userIds creates a new group chat each call. You are the user the run's credential names; selfUserId, the userId of the user you act for as the request names it, is checked against it, and is needed where the credential cannot tell (an API key, or a member without viewUsers: the reused chat must then hold its rule). A chat is created and shared in one atomic call; you own it and the others get view, modify and remove (the other side of a new p2p chat is notified once you are known to be its creator: notified). Returns {chatId, title, type, created, participants}. Then post the message with reaction_create {rootActorId: chatId, type: comment, description}: it notifies them, so confirm a text that speaks for the user first. An Events actor without chatType is a task or an event, not a chat.",
		`{"type":"object","properties":{"type":{"type":"string","enum":["p2p","group"]},"userIds":{"type":"array","minItems":1,"maxItems":200,"uniqueItems":true,"items":{"type":"integer","minimum":1}},"selfUserId":{"type":"integer","minimum":1},"title":{"type":"string","minLength":1,"maxLength":1000}},"required":["type","userIds"],"additionalProperties":false}`, true, c.OpenChat)
	consoleTool(s, "actor_attach", "Add a card to an actor's view (not a reaction or a file): kind actor sets the one actor card it shows (targetId the other actor; replaces the current card), kind smartForm the one Smart Form it opens (targetId the appId; replaces the current one), kind form pins a form card: a new actor of an account template (formId, title, data) or an existing one (targetId), linked by a pinned hierarchy edge, any number per actor. A form card's actor keeps its own access: share it with access_rules_save when others should open it. Returns {actorId, kind, targetId, edgeId}. To detach a card or Smart Form send actor_update with cardActorId or appId \"\". Needs modify on the actor.",
		`{"type":"object","properties":{"actorId":{"type":"string","minLength":1,"maxLength":255},"kind":{"type":"string","enum":["actor","smartForm","form"]},"targetId":{"type":"string","minLength":1,"maxLength":255},"formId":{"type":"integer","minimum":1},"title":{"type":"string","minLength":1,"maxLength":1000},"data":{"type":"object"}},"required":["actorId","kind"],"additionalProperties":false}`, true, c.AttachToActor)
}
